shape_properties = {
    'Sphere': {'Area': 1.5, 'Drag Force': 0.3, 'Velocity': 15},
    'Cube': {'Area': 2.0, 'Drag Force': 0.5, 'Velocity': 15}
}
drag_coeffs = calculate_drag_coefficient(shape_properties)
print('Drag Coefficients:', drag_coeffs)

