def aerodynamic_shape_optimizer(shape_properties):
    drag_coefficients = calculate_drag_coefficient(shape_properties)
    lowest_drag_shape = min(drag_coefficients.items(), key=lambda x: x[1])[0]

    optimized_shapes = {}
    for shape, drag_coefficient in drag_coefficients.items():
        reduced_drag = drag_coefficient * 0.95  # Assume a 5% reduction with optimization
        optimized_shapes[shape] = reduced_drag

    return lowest_drag_shape, optimized_shapes

