def tsp_route_optimizer(delivery_points):
    from itertools import permutations

    def total_route_distance(route):
        return sum(calculate_distance(route[i], route[i + 1]) for i in range(len(route) - 1)) + calculate_distance(route[-1], route[0])

    shortest_route = None
    min_distance = float('inf')
    for perm in permutations(delivery_points):
        current_distance = total_route_distance(perm)
        if current_distance < min_distance:
            shortest_route = perm
            min_distance = current_distance

    return shortest_route, min_distance

