def tsp_route_optimizer(locations):
    from itertools import permutations
    distances = calculate_distances(locations)

    def route_distance(route):
        return sum(distances.get((route[i], route[i+1]), distances.get((route[i+1], route[i]))) for i in range(len(route) - 1))

    shortest_route = None
    min_distance = float('inf')
    for perm in permutations(locations):
        current_distance = route_distance(perm)
        if current_distance < min_distance:
            min_distance = current_distance
            shortest_route = perm

    return shortest_route, min_distance

