def grammatical_pattern_counter(text, patterns):
    # Assume patterns is a list of grammatical structures to count
    counts = {pattern: 0 for pattern in patterns}
    words = text.split()
    for i in range(len(words) - 1):
        for pattern in patterns:
            if ' '.join(words[i:i+len(pattern.split())]) == pattern:
                counts[pattern] += 1
    return counts

# Example usage:
